E = EllipticCurve([0, 0, 0, -2, 0])     # y^2 = x^3 - 2x, genus 1
P = E.gens()[0]
print('rank', E.rank(), ':', [n*P for n in [1, 2, 3]])
pts = []                                  # y^2 = x^5 - x + 1, genus 2
for d in range(1, 13):
    for m in range(-40, 41):
        if gcd(m, d) == 1:
            v = (m/d)^5 - m/d + 1
            p, q = v.numerator(), v.denominator()
            if p >= 0 and isqrt(p)^2 == p and isqrt(q)^2 == q:
                pts.append((m/d, isqrt(p)/isqrt(q)))
print('genus 2, small points:', pts)
